import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.z3u3TMv0.js";const p=JSON.parse('{"title":"Agnes AI","description":"Agnes AI 무료 멀티모달 API — 공식 입구, Free Access Key, 텍스트/이미지/비디오 모델, MiniTavern 입력법.","frontmatter":{"title":"Agnes AI","description":"Agnes AI 무료 멀티모달 API — 공식 입구, Free Access Key, 텍스트/이미지/비디오 모델, MiniTavern 입력법.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"Agnes AI · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Agnes AI 무료 멀티모달 API — 공식 입구, Free Access Key, 텍스트/이미지/비디오 모델, MiniTavern 입력법."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko/free-cloud/agnes-ai"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko/free-cloud/agnes-ai"}]]},"headers":[],"relativePath":"ko/free-cloud/agnes-ai.md","filePath":"ko/free-cloud/agnes-ai.md","lastUpdated":1787224147000}'),n={name:"ko/free-cloud/agnes-ai.md"};function s(d,e,i,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="agnes-ai" tabindex="-1">Agnes AI <a class="header-anchor" href="#agnes-ai" aria-label="Permalink to &quot;Agnes AI&quot;">​</a></h1><p>싱가포르 Sapiens AI의 멀티모달 서비스: 같은 OpenAI 호환 게이트웨이로 <strong>텍스트 대화, 이미지, 비디오</strong>를 다룹니다. **Free Access（무료 체험）**가 있어 유료 Key 없이 채팅·이미지 시범에 적합합니다. 한도·속도 제한은 콘솔 기준.</p><h2 id="공식과-입구" tabindex="-1">공식과 입구 <a class="header-anchor" href="#공식과-입구" aria-label="Permalink to &quot;공식과 입구&quot;">​</a></h2><table tabindex="0"><thead><tr><th>자원</th><th>주소</th></tr></thead><tbody><tr><td>국제</td><td><a href="https://agnes-ai.com/" target="_blank" rel="noreferrer">agnes-ai.com</a></td></tr><tr><td>중국</td><td><a href="https://agnes-ai.cn/" target="_blank" rel="noreferrer">agnes-ai.cn</a></td></tr><tr><td>API 콘솔（가입 / Key）</td><td><a href="https://platform.agnes-ai.com/" target="_blank" rel="noreferrer">platform.agnes-ai.com</a></td></tr><tr><td>개발자 문서</td><td><a href="https://agnes-ai.com/en/docs/overview" target="_blank" rel="noreferrer">agnes-ai.com/en/docs/overview</a></td></tr><tr><td>모델 목록（GitHub）</td><td><a href="https://github.com/AgnesAI-Labs/AgnesAI-Models" target="_blank" rel="noreferrer">AgnesAI-Labs/AgnesAI-Models</a></td></tr><tr><td>API Base URL</td><td><code>https://apihub.agnes-ai.com/v1</code></td></tr></tbody></table><p>지역에 맞게 국제/중국 사이트를 고르세요. <strong>API Key와 Base URL은 콘솔·문서의 현재 표시를 따릅니다</strong>.</p><h2 id="무료-받기-free-access" tabindex="-1">무료 받기（Free Access） <a class="header-anchor" href="#무료-받기-free-access" aria-label="Permalink to &quot;무료 받기（Free Access）&quot;">​</a></h2><ol><li><a href="https://platform.agnes-ai.com/" target="_blank" rel="noreferrer">platform.agnes-ai.com</a>에서 가입·로그인（보통 이메일; 카드 연동은 페이지 기준）.</li><li>개발자 콘솔 → <strong>API Keys</strong> → 만들고 복사（보통 <code>sk-</code>로 시작）.</li><li>MiniTavern에서 <strong>Custom (OpenAI)</strong>（채팅）또는 <strong>Custom (OpenAI Images)</strong>（이미지）에 Base URL과 Key 입력 — 아래.</li></ol><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>무료</td><td><strong>Free Access</strong>: 핵심 Flash 계열 무료 호출（RPM / fair-use）, 개인 체험·demo용</td></tr><tr><td>유료</td><td><strong>Token Plan</strong>: 더 높은 TPS / 월 한도, 생산·고빈도 Agent（필수 아님）</td></tr><tr><td>속도（무료）</td><td>텍스트 약 <strong>20 RPM</strong>; 이미지는 해상도별（1K 약 20 RPM, 높을수록 엄격）; 비디오 약 <strong>1 RPM</strong>（공식 <a href="https://agnes-ai.com/en/docs/tokenplan" target="_blank" rel="noreferrer">Token Plan FAQ</a>）</td></tr><tr><td>카드</td><td>Free Access는 보통 불필요; 상용·고한도는 Token Plan</td></tr></tbody></table><blockquote><p>정책은 바뀝니다. 콘솔에서 Token Plan이 필요하거나 429가 나오면 공식·계정 권한을 따릅니다.</p></blockquote><h2 id="모델-목록" tabindex="-1">모델 목록 <a class="header-anchor" href="#모델-목록" aria-label="Permalink to &quot;모델 목록&quot;">​</a></h2><p>공개 문서·모델 목록의 흔한 ID（<strong>대소문자 구분</strong>）. Flash는 대개 무료; <strong>Pro</strong>는 유료 추론.</p><h3 id="텍스트-대화-비전-이해" tabindex="-1">텍스트（대화 / 비전 이해） <a class="header-anchor" href="#텍스트-대화-비전-이해" aria-label="Permalink to &quot;텍스트（대화 / 비전 이해）&quot;">​</a></h3><p>Chat Completions: <code>POST /v1/chat/completions</code>. MiniTavern: <strong>Custom (OpenAI)</strong>.</p><table tabindex="0"><thead><tr><th>모델 ID</th><th>설명</th></tr></thead><tbody><tr><td><code>agnes-2.5-flash</code></td><td>추천: 대화, 코딩, 도구, 다턴·이미지 이해; 컨텍스트 약 512K</td></tr><tr><td><code>agnes-2.0-flash</code></td><td>이전 Flash, 호환 예비</td></tr><tr><td><code>agnes-2.5-pro</code> / <code>agnes-2.5-pro-alpha</code></td><td>유료 추론（고급 코딩 / 과학 등）, <strong>무료로 쓰지 말 것</strong></td></tr></tbody></table><h3 id="이미지-문생도-도생도" tabindex="-1">이미지（문생도 / 도생도） <a class="header-anchor" href="#이미지-문생도-도생도" aria-label="Permalink to &quot;이미지（문생도 / 도생도）&quot;">​</a></h3><p>Images: 문생도·도생도 모두 <code>POST /v1/images/generations</code>（도생도는 body에 <code>image</code>, OpenAI <code>/images/edits</code> <strong>아님</strong>）. MiniTavern: <strong>Custom (OpenAI Images)</strong>, Base URL 동일 <code>https://apihub.agnes-ai.com/v1</code>; App이 Custom에 이 라우트를 쓰며 참고 이미지 테스트도 generations.</p><table tabindex="0"><thead><tr><th>모델 ID</th><th>설명</th></tr></thead><tbody><tr><td><code>agnes-image-2.1-flash</code></td><td>추천: 고밀도 생성·편집, 유연한 크기</td></tr><tr><td><code>agnes-image-2.0-flash</code></td><td>문생도 / 도생도, URL 또는 Base64</td></tr></tbody></table><h3 id="비디오-문생영상-도생영상" tabindex="-1">비디오（문생영상 / 도생영상） <a class="header-anchor" href="#비디오-문생영상-도생영상" aria-label="Permalink to &quot;비디오（문생영상 / 도생영상）&quot;">​</a></h3><p>Videos: <code>POST /v1/videos</code>（비동기）. 흔한 ID:</p><table tabindex="0"><thead><tr><th>모델 ID</th><th>설명</th></tr></thead><tbody><tr><td><code>agnes-video-v2.0</code></td><td>문생영상, 도생영상, 다중 이미지/키프레임 등</td></tr><tr><td><code>agnes-video-v2.5</code>（또는 문서 Video 2.5）</td><td>신세대 비디오 — <a href="https://agnes-ai.com/en/docs/agnes-video-v20" target="_blank" rel="noreferrer">공식 비디오 문서</a></td></tr></tbody></table><p>MiniTavern에는 <strong>내장 비디오 입구가 없습니다</strong>. 채팅·이미지는 Flash 텍스트/이미지부터.</p><h2 id="minitavern-입력" tabindex="-1">MiniTavern 입력 <a class="header-anchor" href="#minitavern-입력" aria-label="Permalink to &quot;MiniTavern 입력&quot;">​</a></h2><p>일반 절차: <a href="/ultra_guides/ko/manual/model-link">모델 연결</a>.</p><h3 id="채팅" tabindex="-1">채팅 <a class="header-anchor" href="#채팅" aria-label="Permalink to &quot;채팅&quot;">​</a></h3><p>경로: <strong>설정 → 모델 → 모델 연결 → 새로 만들기</strong></p><ol><li>플랫폼 <strong>Custom (OpenAI)</strong></li><li>Base URL: <code>https://apihub.agnes-ai.com/v1</code></li><li>API Key 붙여넣기</li><li>모델 ID <code>agnes-2.5-flash</code>（또는 콘솔의 다른 텍스트）</li><li><strong>테스트</strong> → 성공 후 기본값</li></ol><h3 id="이미지" tabindex="-1">이미지 <a class="header-anchor" href="#이미지" aria-label="Permalink to &quot;이미지&quot;">​</a></h3><p>경로: <strong>설정 → 이미지 생성 → 이미지 연결</strong></p><ol><li>플랫폼 <strong>Custom (OpenAI Images)</strong></li><li>Base URL 동일</li><li>같은 Key; 모델 <code>agnes-image-2.1-flash</code> 등</li><li>테스트 후 <code>/imagine</code> 또는 이미지 입구에 사용</li></ol><p>채팅과 이미지는 분리 가능: 예 채팅 <code>agnes-2.5-flash</code>, 이미지 <code>agnes-image-2.1-flash</code>.</p><h2 id="관련-장" tabindex="-1">관련 장 <a class="header-anchor" href="#관련-장" aria-label="Permalink to &quot;관련 장&quot;">​</a></h2><ul><li><a href="/ultra_guides/ko/free-cloud/">무료 클라우드 개요</a> — 다른 벤더 무료/체험</li><li><a href="/ultra_guides/ko/free-cloud/#무료-이미지-생성">무료 이미지</a></li><li><a href="/ultra_guides/ko/manual/model-link">모델 연결</a></li><li><a href="/ultra_guides/ko/local/image-gen/">이미지 모델 배포</a> — 로컬 A1111 / ComfyUI</li></ul>',32)])])}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
